/**
 * Service worker for the Konachan browser.
 *
 * Hand-written replacement for the 68 KB workbox bundle that used to live here.
 * That bundle shipped a precache manifest generated by the pre-Leptos Vite
 * build (`assets/index-*.js`, `registerSW.js`, `manifest.webmanifest`, ...);
 * every URL in it 404s against the current Trunk output, so `install` rejected
 * with `bad-precaching-response` and the worker never reached `activated` —
 * none of its runtime routes were ever used either.
 *
 * No manifest is generated at build time: Trunk content-hashes the bundle, so
 * the names are only known afterwards, and a stale list turns `install` into a
 * hard failure. Instead the boot set is discovered from the served shell while
 * installing (see `warmShell`), which cannot drift from the build.
 *
 * Bump `VERSION` whenever a strategy changes: activation drops every cache
 * whose name is not in `CACHES`.
 */

const VERSION = "1";
const PAGES = `kona-pages-v${VERSION}`;
const ASSETS = `kona-assets-v${VERSION}`;
const IMAGES = `kona-images-v${VERSION}`;
const CACHES = [PAGES, ASSETS, IMAGES];

/** A navigation that has not answered by then falls back to the cache. */
const NAVIGATION_TIMEOUT_MS = 4000;
/** Image entries are evicted oldest-first beyond this count (was 50 in workbox). */
const IMAGE_LIMIT = 60;
/** Navigations are all `/` in this SPA; the cap is only a guard. */
const PAGE_LIMIT = 10;
/** Boot set plus fonts: a few builds' worth of hashed names stay around. */
const ASSET_LIMIT = 12;

const isHttp = (url) => url.protocol === "http:" || url.protocol === "https:";
const sameOrigin = (url) => url.origin === self.location.origin;

/** Deletes the oldest entries until `limit` remain (FIFO, see `imageFirst`). */
async function trim(cache, limit) {
  const keys = await cache.keys();
  const excess = Math.max(0, keys.length - limit);
  for (const key of keys.slice(0, excess)) {
    await cache.delete(key);
  }
}

/**
 * Stores the boot set, discovered from the shell document itself.
 *
 * Only what is needed to start offline is cached: the JavaScript, the
 * stylesheet and the WASM bundle referenced by `index.html`. Fonts and the
 * 1.4 MB favicon are left to the runtime rules so the first visit is not
 * paying for them.
 */
async function warmShell() {
  try {
    const shell = await fetch("/", { cache: "no-store" });
    if (!shell.ok) return;

    const pages = await caches.open(PAGES);
    await pages.put("/", shell.clone());
    await trim(pages, PAGE_LIMIT);

    const html = await shell.text();
    const assets = await caches.open(ASSETS);
    await Promise.all(
      [...new Set(html.match(/\/[\w.-]+\.(?:js|css|wasm)/g) ?? [])].map(async (url) => {
        const response = await fetch(url);
        if (response.ok) await assets.put(url, response);
      }),
    );
    await trim(assets, ASSET_LIMIT);
  } catch {
    // A failed warm-up must not fail the install: the runtime rules fill the
    // same caches on the first controlled load.
  }
}

self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      // A waiting worker would keep serving the previous strategy until every
      // tab is closed. Cache names are versioned, so taking over immediately
      // cannot mix entries from two strategies.
      await self.skipWaiting();
      await warmShell();
    })(),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const stale = (await caches.keys()).filter((name) => !CACHES.includes(name));
      await Promise.all(stale.map((name) => caches.delete(name)));
      await self.clients.claim();
    })(),
  );
});

self.addEventListener("fetch", (event) => {
  const request = event.request;
  if (request.method !== "GET") return;

  const url = new URL(request.url);
  if (!isHttp(url)) return;
  // Range requests cannot be satisfied from a full-body cache entry.
  if (request.headers.has("range")) return;

  if (request.mode === "navigate") {
    if (sameOrigin(url)) event.respondWith(navigate(event));
    return;
  }

  if (!sameOrigin(url)) {
    // Thumbnails and samples live on konachan.com, so these responses are
    // cross-origin and opaque (status 0). They are still storable, and this is
    // where most of the offline value comes from.
    if (request.destination === "image") event.respondWith(imageFirst(event));
    return;
  }

  // The post API is query-addressed and its answers go stale in ways the UI
  // cannot detect, so it stays network-only.
  if (url.pathname.startsWith("/api/")) return;

  // The WASM bundle is fetched by `wasm-bindgen` with an empty `destination`,
  // so it needs an explicit rule.
  if (url.pathname.endsWith(".wasm")) {
    event.respondWith(cacheFirst(event, ASSETS));
    return;
  }

  switch (request.destination) {
    case "style":
    case "script":
    case "worker":
    case "font":
      event.respondWith(staleWhileRevalidate(event, ASSETS));
      return;
    case "image":
      event.respondWith(imageFirst(event));
      return;
    default:
      // Documents other than navigations, JSON, and anything else unclassified
      // are not cached: a wrong strategy here outlives the tab.
      return;
  }
});

/** Network first, cached document (or the warmed `/`) as the offline fallback. */
async function navigate(event) {
  const request = event.request;
  const cache = await caches.open(PAGES);

  let response;
  try {
    response = await fetchWithTimeout(request);
  } catch {
    response = undefined;
  }

  if (response && response.ok) {
    await cache.put(request, response.clone());
    await trim(cache, PAGE_LIMIT);
    return response;
  }

  const fallback = (await cache.match(request)) || (await cache.match("/"));
  // If nothing is cached either, keep the network's own failure instead of
  // masking it with an empty response.
  return fallback || response || Response.error();
}

/** `fetch` with an abort timer, so a dead connection cannot hang a navigation. */
async function fetchWithTimeout(request) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), NAVIGATION_TIMEOUT_MS);
  try {
    return await fetch(request, { signal: controller.signal });
  } finally {
    clearTimeout(timer);
  }
}

/**
 * Answers from the cache when possible and refreshes in the background.
 *
 * Not `async`: `event.waitUntil` has to be registered before the handler
 * returns, otherwise the write is dropped when the cached copy answers first.
 */
function staleWhileRevalidate(event, cacheName) {
  const request = event.request;
  const update = caches.open(cacheName).then(async (cache) => {
    const response = await fetch(request);
    if (response.ok) await cache.put(request, response.clone());
    return response;
  });
  event.waitUntil(update.catch(() => {}));
  return caches.match(request).then((cached) => cached || update);
}

/** Cached copy first, network otherwise; used for content-hashed assets. */
async function cacheFirst(event, cacheName) {
  const request = event.request;
  const cache = await caches.open(cacheName);
  const cached = await cache.match(request);
  if (cached) return cached;

  const response = await fetch(request);
  if (response.ok) await cache.put(request, response.clone());
  return response;
}

/**
 * Cached copy first, network otherwise, oldest entries evicted beyond the cap.
 *
 * There is no expiry: opaque responses expose neither `Date` nor a body the
 * worker could read, so per-entry age is unknowable. `VERSION` is the lever.
 */
async function imageFirst(event) {
  const request = event.request;
  const cache = await caches.open(IMAGES);
  const cached = await cache.match(request);
  if (cached) return cached;

  const response = await fetch(request);
  if (response.ok || response.type === "opaque") {
    await cache.put(request, response.clone());
    await trim(cache, IMAGE_LIMIT);
  }
  return response;
}
